#include <version>
#if !defined(__cpp_lib_span) || __cpp_lib_span < 202002L
#error "This example requires the C++20 span facility"
#endif
#include <array>
#include <iostream>
#include <span>

int sum(std::span<const int> values)
{
    int total{};
    for (int value : values) total += value;
    return total;
}

int main()
{
    const std::array<int, 3> pages{2, 3, 4};
    std::cout << sum(pages) << '\n';
}
